      process.stdout.write("ERROR: invalid operator\n");
      rl.close();
      return;
    }
    const result = compare(a, op, b);
    process.stdout.write("result: " + result + "\n");
    process.stdout.write("rule: " + ruleFor(a, op, b) + "\n");
    rl.close();
    return;
  }
  rl.close();
}

