  const key = JSON.stringify(a) + "|" + op + "|" + JSON.stringify(b);
  if (RULES.has(key)) return RULES.get(key);
  if (op === "===") return "no coercion with ===";
  return "== may coerce types before comparing";
}

function compare(a, op, b) {
  if (op === "==") return a == b;
  if (op === "===") return a === b;
  return null;
}

