  scheduleMicro(() => {
    log("m1");
    scheduleMicro(() => log("m2"));
  });
  scheduleTask(() => {
    log("t1");
    done();
  });
}

function runTrick({ log, scheduleMicro, scheduleTask, done }) {
  log("start");
  scheduleMicro(() => log("micro"));
  scheduleTask(() => {
    log("timer");
    done();
  });
  log("end");
}

