What does `counter.get()` return?

```js
function createCounter(start) {
  let count = start;
  return {
    inc() { count += 1; },
    get() { return count; },
  };
}

const counter = createCounter(10);
counter.inc();
counter.inc();
```

```js
const a = createCounter(0);
const b = createCounter(100);
a.inc();
console.log(a.get(), b.get());
```

